function pickCache(existing, key, restoreKeys) {
  if (existing.includes(key)) return key;
  for (const prefix of restoreKeys) {
    const hits = existing.filter((k) => k.startsWith(prefix));
    if (hits.length) return hits[hits.length - 1];
  }
  return null;
}

from itertools import product

def expand(matrix, exclude):
    keys = list(matrix)
    out = []
    for combo in product(*matrix.values()):
        row = dict(zip(keys, combo))
        if any(all(row.get(k) == v for k, v in ex.items()) for ex in exclude):
            continue
        out.append(row)
    return out

