function canaryVerdict(canary, baseline, minRequests, maxDelta) {
  if (canary.requests < minRequests) return "wait";
  const c = canary.errors / canary.requests;
  const b = baseline.requests ? baseline.errors / baseline.requests : 0;
  return c - b > maxDelta ? "rollback" : "promote";
}

