def median_lead_time(pairs):
    if not pairs:
        return None
    hours = sorted((d - c) / 3600 for c, d in pairs)
    mid = len(hours) // 2
    if len(hours) % 2:
        return hours[mid]
    return (hours[mid - 1] + hours[mid]) / 2
